import{_ as s,o as a,c as i,ao as t}from"./chunks/framework.B4GKDi6j.js";const k=JSON.parse('{"title":"QuantumToolbox Settings","description":"","frontmatter":{},"headers":[],"relativePath":"users_guide/settings.md","filePath":"users_guide/settings.md","lastUpdated":null}'),n={name:"users_guide/settings.md"};function l(o,e,p,h,d,r){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="doc:QuantumToolbox-Settings" tabindex="-1">QuantumToolbox Settings <a class="header-anchor" href="#doc:QuantumToolbox-Settings" aria-label="Permalink to &quot;QuantumToolbox Settings {#doc:QuantumToolbox-Settings}&quot;">​</a></h1><p>In this section, we introduce the default global settings used throughout the package and show how to modify them.</p><p>All settings are stored in <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolboxCore.settings"><code>QuantumToolbox.settings</code></a>.</p><div class="warning custom-block"><p class="custom-block-title">Differences from QuTiP</p><p>Due to the differences in programming languages, solving algorithms, and many other reasons, these global settings (including their default values and usage) may be very different from those in <code>Python QuTiP</code>.</p></div><h2 id="List-of-settings" tabindex="-1">List of settings <a class="header-anchor" href="#List-of-settings" aria-label="Permalink to &quot;List of settings {#List-of-settings}&quot;">​</a></h2><p>Here, we list out each setting along with the specific functions that will use it.</p><ul><li><p><code>tidyup_tol::Float64 = 1.0e-14</code> : tolerance for <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolboxCore.tidyup"><code>tidyup</code></a>, <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolboxCore.tidyup!"><code>tidyup!</code></a> and <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolboxCore.to_sparse"><code>to_sparse</code></a>.</p></li><li><p><code>auto_tidyup::Bool = true</code> : Automatically tidyup during the following situations:</p><ul><li><p>Solving for eigenstates, including <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolbox.eigenstates"><code>eigenstates</code></a>, <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolbox.eigsolve"><code>eigsolve</code></a>, <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolbox.eigsolve_al"><code>eigsolve_al</code></a></p></li><li><p>Creating <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolbox.bloch_redfield_tensor"><code>bloch_redfield_tensor</code></a> or <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolbox.brterm"><code>brterm</code></a>, and solving <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolbox.brmesolve"><code>brmesolve</code></a>.</p></li></ul></li><li><p><code>progressmeter_kwargs::NamedTuple = (showspeed = true, printed = true)</code> : Default keyword arguments for progress bar in <a href="https://github.com/timholy/ProgressMeter.jl" target="_blank" rel="noreferrer"><code>ProgressMeter.jl</code></a>. This allows the customization of progress bar.</p></li><li><p><code>default_eltype::Type = ComplexF64</code> : Element type of the quantum objects created without specifying it, such as <code>destroy(N)</code> or <code>fock(N, j)</code>. It must be a concrete floating point or complex type, such as <code>ComplexF32</code> or <code>Float64</code>. A real type can be used for real-valued systems: functions that need complex numbers, such as <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolboxCore.sigmay"><code>sigmay</code></a> or <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolboxCore.rand_ket"><code>rand_ket</code></a>, then use its complex version.</p></li><li><p><code>show_eltype_warning::Bool = true</code> : Warn (once) when a quantum object is created with an element type more general than <code>default_eltype</code>, e.g., <code>0.5 * destroy(N)</code> with <code>default_eltype = ComplexF32</code>, or a complex state with a real <code>default_eltype</code>.</p></li></ul><h2 id="Change-default-settings" tabindex="-1">Change default settings <a class="header-anchor" href="#Change-default-settings" aria-label="Permalink to &quot;Change default settings {#Change-default-settings}&quot;">​</a></h2><p>First, we can check the current <a href="/QuantumToolbox.jl/dev/resources/api#QuantumToolboxCore.settings"><code>QuantumToolbox.settings</code></a>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> QuantumToolbox</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">QuantumToolbox</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">settings</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">QuantumToolbox.jl Settings</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">--------------------------</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">tidyup_tol           = 1.0e-14</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">auto_tidyup          = true</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">progressmeter_kwargs = (showspeed = true, printed = true)</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">default_eltype       = ComplexF64</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">show_eltype_warning  = true</span></span></code></pre></div><p>Next, one can overwrite the default settings by</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">QuantumToolbox</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">settings</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tidyup_tol </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1e-10</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">QuantumToolbox</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">settings</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auto_tidyup </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">QuantumToolbox</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">settings</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">QuantumToolbox.jl Settings</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">--------------------------</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">tidyup_tol           = 1.0e-10</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">auto_tidyup          = false</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">progressmeter_kwargs = (showspeed = true, printed = true)</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">default_eltype       = ComplexF64</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">show_eltype_warning  = true</span></span></code></pre></div><h2 id="Change-the-default-element-type" tabindex="-1">Change the default element type <a class="header-anchor" href="#Change-the-default-element-type" aria-label="Permalink to &quot;Change the default element type {#Change-the-default-element-type}&quot;">​</a></h2><p>By default, quantum objects are created with element type <code>ComplexF64</code>. To use a lower precision, for example to run faster or to save memory, one can change <code>default_eltype</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">QuantumToolbox</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">settings</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default_eltype </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ComplexF32</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> destroy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">eltype</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(a)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">ComplexF32</span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;"> (alias for </span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;">Complex{Float32}</span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;">)</span></span></code></pre></div><p>Note that a <code>Float64</code> number promotes the element type back to <code>ComplexF64</code>, following the usual promotion rules of Julia. A warning is shown (once per session) when this happens:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">eltype</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">ComplexF64</span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;"> (alias for </span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;">Complex{Float64}</span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;">)</span></span></code></pre></div><p>To keep the lower precision, use <code>Float32</code> numbers instead, such as <code>0.5f0</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">eltype</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5f0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">ComplexF32</span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;"> (alias for </span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;">Complex{Float32}</span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;">)</span></span></code></pre></div><p>An element type given explicitly is still used. The warning above cannot tell it apart from a promotion, so set <code>QuantumToolbox.settings.show_eltype_warning = false</code> if a more general type is intended:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">eltype</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">destroy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ComplexF64, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">ComplexF64</span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;"> (alias for </span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;">Complex{Float64}</span><span style="--shiki-light:#959da5;--shiki-dark:#959da5;">)</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Change <code>progressmeter_kwargs</code> and <code>default_eltype</code> with a separate statement</p><p>Changing <code>progressmeter_kwargs</code> or <code>default_eltype</code> redefines a method, so code that is already running keeps seeing the previous value: reading <code>default_eltype</code> there throws an error, and the progress bar keeps the previous <code>progressmeter_kwargs</code>. Change them with a separate statement, for example at the beginning of your script, and not inside a function or a block (such as <code>begin</code>, <code>let</code>, <code>try</code> or <code>for</code>) that also uses them. For the same reason, they cannot be changed by a package while it is being precompiled: packages should pass the element type explicitly instead, e.g., <code>destroy(T, N)</code>.</p></div>`,28)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
